   499	func formatCheckpointMetricDelta(delta *checkpointTokensMetricDelta, formatValue func(int) string) string {
   500		if delta == nil {
   501			return "unavailable"
   502		}
   503		from := formatValue(delta.Baseline)
   504		to := formatValue(delta.Current)
   505		if delta.Direction == "unchanged" {
   506			return fmt.Sprintf("unchanged (%s -> %s)", from, to)
   507		}
   508		if delta.ChangePercent == nil {
   509			return fmt.Sprintf("%s (%s -> %s)", delta.Direction, from, to)
   510		}
   511		return fmt.Sprintf("%s %s (%s -> %s)", delta.Direction, formatPercent(absFloat(*delta.ChangePercent)), from, to)
   512	}
