   202				}
   203				metadataReadWarning = true
   204				continue
   205			}
   206			metas = append(metas, meta)
   207		}
   208		sessionUsage := aggregateCheckpointTokenUsage(metas)
   209		if !metadataReadWarning && sessionUsage != nil {
