+func writeSessionTokensText(w io.Writer, report sessionTokensReport) {
+	fmt.Fprintln(w, "Session tokens")
+	fmt.Fprintln(w)
+	fmt.Fprintf(w, "Session: %s\n", report.SessionID)
+	fmt.Fprintf(w, "Agent:   %s\n", report.Agent)
