package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()

	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if err != nil {
		fatalf("resolve data API token: %v", err)
	}
	client := api.NewClientWithBaseURL(token, api.BaseURL())

	runPath := "/api/v1/trails/gh/entireio/cli/542/runs/trail-semantic-diff"
	resp, err := client.Post(ctx, runPath, map[string]any{})
	if err != nil {
		fatalf("POST %s: %v", runPath, err)
	}
	body, contentType := read(resp)
	fmt.Printf("start_eval: HTTP %d content_type=%s\n%s\n", resp.StatusCode, contentType, summarize(body))
	if strings.Contains(contentType, "text/html") || bytesHas(body, "Cloudflare Access") {
		fmt.Println("start_eval_result: blocked_by_web_session_or_cloudflare")
		return
	}
	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return
	}

	for i := 0; i < 6; i++ {
		if i > 0 {
			time.Sleep(5 * time.Second)
		}
		fmt.Printf("\npoll %d:\n", i+1)
		get(ctx, client, "/api/v1/trails/gh/entireio/cli/542/checks")
		get(ctx, client, "/api/v1/trails/gh/entireio/cli/542")
	}
}

func get(ctx context.Context, client *api.Client, path string) {
	resp, err := client.Get(ctx, path)
	if err != nil {
		fmt.Printf("%s: error: %v\n", path, err)
		return
	}
	body, contentType := read(resp)
	fmt.Printf("%s: HTTP %d content_type=%s\n%s\n", path, resp.StatusCode, contentType, summarize(body))
}

func read(resp *http.Response) ([]byte, string) {
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 16<<20))
	if err != nil {
		return []byte(fmt.Sprintf("read error: %v", err)), resp.Header.Get("Content-Type")
	}
	return body, resp.Header.Get("Content-Type")
}

func summarize(body []byte) string {
	var data map[string]any
	if err := json.Unmarshal(body, &data); err != nil {
		text := strings.TrimSpace(string(body))
		if len(text) > 1600 {
			text = text[:1600] + "\n... truncated ..."
		}
		return text
	}
	parts := []string{}
	for _, key := range []string{"runId", "run_id", "id", "status", "state", "message", "error", "automation", "head_sha"} {
		if v, ok := data[key]; ok {
			parts = append(parts, fmt.Sprintf("%s=%v", key, v))
		}
	}
	if trail, ok := data["trail"].(map[string]any); ok {
		parts = append(parts, "trail="+trailSummary(trail))
	}
	if cps, ok := data["checkpoints"].([]any); ok {
		parts = append(parts, fmt.Sprintf("checkpoints=%d", len(cps)))
	}
	if checks, ok := data["checks"].([]any); ok {
		parts = append(parts, fmt.Sprintf("checks=%d", len(checks)))
	}
	if len(parts) > 0 {
		return strings.Join(parts, "; ")
	}
	out, _ := json.MarshalIndent(data, "", "  ")
	text := string(out)
	if len(text) > 1600 {
		text = text[:1600] + "\n... truncated ..."
	}
	return text
}

func trailSummary(obj map[string]any) string {
	parts := []string{}
	for _, key := range []string{"number", "branch", "status", "phase", "checkpoint_count", "head_sha"} {
		if v, ok := obj[key]; ok {
			parts = append(parts, fmt.Sprintf("%s=%v", key, v))
		}
	}
	return strings.Join(parts, ",")
}

func bytesHas(body []byte, needle string) bool {
	return strings.Contains(string(body), needle)
}

func fatalf(format string, args ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}

