	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if err != nil {
		fatalf("resolve token: %v", err)
	}
	client := api.NewClientWithBaseURL(token, api.BaseURL())
	resp, err := client.Get(ctx, "/api/v1/cache/repos")
	if err != nil {
		fatalf("GET repos: %v", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 16<<20))
	if err != nil {
		fatalf("read body: %v", err)
	}
	fmt.Printf("HTTP %d\n", resp.StatusCode)
	var data struct {
		Repos []map[string]any `json:"repos"`
	}
	if err := json.Unmarshal(body, &data); err != nil {
		fmt.Println(string(body))
		return
	}
	for _, repo := range data.Repos {
		if repo["full_name"] == "entireio/cli" {
			out, _ := json.MarshalIndent(repo, "", "  ")
			fmt.Println(string(out))
			return
		}
	}
	fmt.Println("entireio/cli not found")
}

func fatalf(format string, args ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}

