	if len(cols) < 2 {
		t.Fatalf("expected multiple experimental commands, got %d", len(cols))
	}
	for i, col := range cols {
		if col != cols[0] {
			t.Fatalf("summary column %d (%d) does not match first column (%d); descriptions are misaligned", i, col, cols[0])
		}
