	if err != nil {
		return checkpointTokensReport{}, lookup, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	if summary == nil || len(summary.Sessions) == 0 {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), "Checkpoint not found.")
