	}
	cmd.Flags().StringVar(&projectID, "project", "", "owning project ULID (required)")
	cmd.Flags().StringVar(&clusterHost, "cluster-host", "", "public host of the cluster to pin the repo to (defaults to the jurisdiction default)")
